<template>
    <el-radio-group v-model="selectedFilter" class="neumorphic-radio-group">
        <el-radio-button value="calendar" class="neumorphic-button">Сейчас</el-radio-button>
        <el-radio-button value="today" class="neumorphic-button">Сегодня</el-radio-button>
        <el-radio-button value="tomorrow" class="neumorphic-button">Завтра</el-radio-button>
        <el-radio-button value="all" class="neumorphic-button">Все</el-radio-button>
    </el-radio-group>
    <hr>
    <button v-if="selectedFilter==='calendar'" @click="setTaskToCalendar">Заполнить календарь</button>
    <button  v-if="selectedFilter==='0'" @click="setTaskCompleted">Отметить завершенные</button>
    <ul class="tasks">
        <li>{{getSortedTodos.length}} ({{getTotalTime}} ч.) <span style="float: right"
        ><span title="Времени сегодня">{{log.today}}</span> /
            <span title="В среднем за неделю">{{log.week}}</span> /
            <span title="В среднем за месяц">{{log.month}}</span>
            (<span title="Уровень дисциплины">{{calc.averageCalc?.toFixed(2)}}</span> /
            <span title="Проверка дисциплины">{{calc.prevAvg?.toFixed(2)}}</span>)
        </span></li>
        <li
            v-for="todo in getSortedTodos"
            :key="todo.id"
            :class="['task', todo.task_color, { completed: todo.completed || isCompleting(todo.task_uuid) }]"
        >
            <span
                class="task-description"
                :title="'task_date: ' + taskDate(todo.task_date) + ', last_execution: ' + taskDate(todo.last_execution)
                 + ', repeat: ' + repeat(todo)"
                @click="!todo.completed && togglePopover(todo.task_uuid)"
            >
                ({{ todo.task_time}}) {{ todo.task_title }}
                <span class="task-repeat_index">({{ toNumber(todo.repeat_index).toFixed(2) }})</span>

                <span v-if="parseInt(todo.start_date)"> {{ ((currentTime - todo.start_date) / (60*1000)).toFixed(2)}}</span>
                <span v-else-if="parseInt(todo.task_finish_date)"> {{ ((todo.task_finish_date) / (60*1000)).toFixed(2)}}</span>
            </span>

            <div v-if="visiblePopover === todo.task_uuid" class="editable-description">
                <textarea
                    v-model="todo.task_description"
                    rows="3"
                    style="width: 100%; margin-top: 8px;"
                ></textarea>
                <button @click="closeEditor(todo)" style="margin-top: 4px;">✅ Сохранить</button>
            </div>


            <div v-if="!todo.completed && !isBusy(todo.task_uuid) && visiblePopover !== todo.task_uuid" class="buttons">
                <!-- Кнопки Старт / Стоп -->
                <span style="margin-right: 8px;">
                    <button class="start" v-if="todo.start_date == 0" @click="startTask(todo)">▶️</button>
                    <span v-else>
                      <button  class="pause" @click.stop="pauseTask(todo)">⏸</button>
                    </span>
                </span>
                <span  v-if="todo.start_date == 0" class="done" @click.stop="toggleTodo(todo, 'done')">✅</span>
                <span v-else class="done" >
                    <button @click.stop="toggleTodo(todo, 'stop')">⏹</button>
                </span>
                <span v-if="selectedFilter==='calendar'" class="delete" @click.stop="deleteTodo(todo)" title="Нет возможности, нет сил сделать">ⓧ</span>
            </div>
        </li>

    </ul>
</template>

<script>
import '../assets/styles/components/TodoList.css';
import {calcExecutions, makeTaskDone, setTaskCompleted, setTaskToCalendar, sumExecutedMinutesToday, taskDate, taskSort} from "@/utils/tasks.js";
import {addEvent, deleteEvent, listEvents, updateEvent} from "@/utils/calendar.js";
import {toNumber} from "@/utils/numbers.js";
import throttle from 'lodash/throttle';

export default {
    data() {
        return {
            visiblePopover: null,
            total: 0,
            timer: 0,
            currentTime: 0,
            log:{},
            selectedFilter: 'calendar',
            busyUuids: new Set(),
            completingUuids: new Set()
        };
    },
    computed: {
        todos() {
            return this.$store.getters["todos/getTodos"];
        },
        events() {
            return this.$store.getters["events/getEvents"];
        },
        calc(){
            return  this.$store.getters["settings/allCalc"];
        },
        getSortedTodos(){
            switch (this.selectedFilter) {
                case 'calendar':
                    // Получаем список отфильтрованных задач
                    const filteredTodos = this.getFilteredTodos();
                    // Создаём пустой массив для результата
                    let sortedTodos = [];

                    sortedTodos = sortedTodos.concat(
                        this.todos.filter(todo => {
                            // Проверка, есть ли уже такой task_uuid в sortedTodos
                            const alreadyIncluded = sortedTodos.some(e => e.task_uuid === todo.task_uuid);

                            // Добавляем только если его ещё нет и поля корректны
                            return !alreadyIncluded &&
                                ((parseInt(todo.task_time) &&
                                    parseInt(todo.task_finish_date)) || parseInt(todo.start_date));
                        })
                    );

                    // Создаём карту задач для быстрого доступа по UUID
                    const todoMap = new Map();
                    filteredTodos.forEach(todo => {
                        todoMap.set(todo.task_uuid, todo);
                    });
                    const existMap = new Map();
                    sortedTodos.forEach(todo => {
                        existMap.set(todo.task_uuid, todo);
                    });

                    // Проходим по событиям и добавляем соответствующие задачи в результат
                    this.events.forEach(event => {
                        const uuids = event.description?.split('\n');
                        let task_done_color = '7';
                        if (event.colorId===task_done_color) return;
                        uuids?.forEach(uuid=>{
                            if (uuid && todoMap.has(uuid) && !existMap.has(uuid)) {
                                sortedTodos.push(todoMap.get(uuid));
                            }
                        });
                    });
                    // Возвращаем отсортированные задачи
                    return sortedTodos;
                case 'all':
                    return this.getFilteredTodos().sort((a, b) => {
                        let sort = function (todo) {
                            let sort = toNumber(todo.repeat_index);
                            const match = todo.task_description.toString().match(/(\d+)d/);
                            if (match) {
                                sort = match[1]
                            }
                            return sort
                        }
                        return this.repeat(b)/sort(b) - (this.repeat(a)/sort(a))
                    });
                case 'today':
                case 'tomorrow':
                default:
                    return this.getFilteredTodos().sort((a, b) => {
                        return taskSort(a) - taskSort(b)
                    });
            }
        },
        getTotalTime() {
            let summ = 0;
            this.getSortedTodos.forEach((task) => {
                summ += Number(task.task_time) || 0;
            });
            return (summ / 60).toFixed(2);
        }
    },
    props: {
        filter: {
            type: String,
            default: 'all'
        }
    },
    methods: {
        setTaskCompleted,
        setTaskToCalendar,
        taskDate,
        taskSort,
        toNumber,
        getFilteredTodos() {
            const task_done_color = '7';
            const now = new Date();
            //const today = new Date().getTime();
            const tomorrow = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 23, 59, 0, 0).getTime();
            const end_today = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0, 1).getTime();
            return this.todos.filter(todo => {
                if (todo.task_title.includes('task_title')) return false;
                const start = parseInt(todo.task_date);
                switch (this.selectedFilter) {
                    case 'calendar':
                        const calendarEvents = this.events;
                        const matchingEvent = calendarEvents?.find(
                            event => {
                                return event.description?.includes(todo.task_uuid)
                            }
                        );
                        return (start < end_today || matchingEvent?.colorId !== task_done_color);
                    case 'today':
                        return start < end_today;
                    case 'tomorrow':
                        return start > end_today && start < tomorrow;
                    default:
                        return true;
                }
            });
        },
        repeat(todo){
            return ((new Date().getTime() - todo.last_execution)/(24 * 60 * 60 * 1000)).toFixed(2)
        },
        closeEditor(todo) {
            this.visiblePopover = null;
            this.$store.dispatch("todos/updateTodo", { ...todo }); // принудительное сохранение
        },

        async toggleTodo(todo, reason = 'done') {
            this.doAuth();
            let task_uuid = todo.task_uuid
            if (this.busyUuids.has(task_uuid)) {
                console.log('[toggleTodo] ПРОПУЩЕНО — busy-лок:', task_uuid, todo.task_title);
                return false;
            }
            console.log('[toggleTodo] ВХОД:', {
                task_uuid, task_title: todo.task_title, start_date: todo.start_date,
                task_finish_date: todo.task_finish_date, completed: todo.completed,
                number_of_executions: todo.number_of_executions, task_time: todo.task_time,
                minutesSpent: todo.minutesSpent, reason
            });
            this.busyUuids.add(task_uuid);
            this.completingUuids.add(task_uuid);
            try {
                const task = { ...todo };
                const start_date = parseInt(task.start_date);
                const finish_date = parseInt(task.task_finish_date);
                task.completed = true;
                // финально закрываем задачу, которая уже была на паузе → не начисляем награду/запись заново
                let skipReward = false;
                // Формула task_time при завершении задачи:
                //   task_time = ceil(((всё время по задаче за сегодня + текущий отрезок) + было_task_time) / 2)
                // где «всё время за сегодня» — сумма execution_time из журнала task_executions за сегодня.
                // Награда/событие/журнал считаются по фактическому времени (minutesSpent),
                // а усреднённое значение пишется в колонку task_time последним.
                const oldTaskTime = Number(task.task_time) || 0;
                if (start_date) {
                    // ⏸ пауза / ⏹ стоп: запущенный таймер → есть текущий (live) отрезок + уже зафиксированные сегодня сегменты
                    const minutesSpent = Math.ceil((Date.now() - start_date) / 60000);
                    const priorToday = await sumExecutedMinutesToday(this.$store, task_uuid);
                    task.minutesSpent = minutesSpent;                 // событие/награда/журнал = только текущий отрезок
                    task.task_time = Math.ceil(((priorToday + minutesSpent) + oldTaskTime) / 2);
                    task.start_date = 0;
                    console.log('[toggleTodo]', reason, ': priorToday:', priorToday, '+ minutesSpent:', minutesSpent, '+ old:', oldTaskTime, '→ task_time:', task.task_time);
                } else if (finish_date) {
                    // ✅ завершено по задаче, которая была на паузе: live-отрезка нет, все сегменты уже в журнале за сегодня
                    const totalToday = await sumExecutedMinutesToday(this.$store, task_uuid);
                    if (totalToday > 0) {
                        task.minutesSpent = totalToday;               // событие = фактическое время за день
                        task.task_time = Math.ceil((totalToday + oldTaskTime) / 2);
                        skipReward = true;                            // награду не начисляем повторно (уже выдана на паузах)
                        console.log('[toggleTodo] done(была на паузе): totalToday:', totalToday, '+ old:', oldTaskTime, '→ task_time:', task.task_time);
                    } else {
                        console.log('[toggleTodo] done(была на паузе), журнал пуст → оставляем план:', task.task_time);
                    }
                } else {
                    // ✅ завершено без запуска: ни журнала, ни live-отрезка нет → «за сегодня»=0, «текущий»=0
                    task.minutesSpent = oldTaskTime;                  // событие/награда/журнал = плановое время
                    task.task_time = Math.ceil(oldTaskTime / 2);      // ceil((0 + old)/2)
                    console.log('[toggleTodo] done(без запуска): old:', oldTaskTime, '→ task_time:', task.task_time);
                }
                const endDate = new Date();
                const timeSpent = task.minutesSpent ?? task.task_time;
                const startDate = new Date(endDate.getTime() - timeSpent * 60 * 1000);
                const task_done_color = '7';
                const event = {
                    summary: task.task_title,
                    description: task.task_uuid,
                    colorId: task_done_color,
                    start: {
                        dateTime: startDate.toISOString(),
                        timeZone: 'Europe/Samara',
                    },
                    end: {
                        dateTime: endDate.toISOString(),
                        timeZone: 'Europe/Samara',
                    },
                };

                let list = await listEvents(this.$store);

                let exist = list.filter(event => event.description?.includes(task_uuid));

                // если событие уже есть (задача в работе или уже выполнена) — обновляем его,
                // иначе добавляем новое; повторная отметка/пауза всегда завершают задачу с наградой
                if (exist.length) {
                    console.log('[toggleTodo] событие уже есть → updateEvent:', { id: exist[0].id, colorId: exist[0].colorId, summary: exist[0].summary });
                    event.summary = exist[0].summary;
                    event.id = exist[0].id
                    await updateEvent(event)
                } else {
                    console.log('[toggleTodo] события нет → addEvent (новое)');
                    await addEvent(event);
                    //т.к. задача была не на сегодня
                    task.break_multiplier = parseFloat(task.break_multiplier) + 1;
                    task.repeat_index = toNumber(task.repeat_index) - 0.1;
                    task.task_sort = toNumber(task.task_sort) - 0.02;
                }
                setTimeout(async () => {
                    try {
                        console.log('[toggleTodo] setTimeout(300) → makeTaskDone:', { task_uuid, minutesSpent: task.minutesSpent, start_date: task.start_date, task_time: task.task_time, skipReward });
                        await makeTaskDone(task, this.$store, { skipReward });
                        this.log = await calcExecutions(this.$store);
                    } catch (err) {
                        console.error('Ошибка выполнения задачи:', err);
                    } finally {
                        try {
                            await listEvents(this.$store);
                            await this.$store.dispatch("todos/initTodos");
                        } catch (err) {
                            console.error('Ошибка обновления данных после выполнения:', err);
                        }
                        this.busyUuids.delete(task_uuid);
                        this.completingUuids.delete(task_uuid);
                        const after = this.$store.getters['todos/getTodos']?.find(t => t.task_uuid === task_uuid);
                        console.log('[toggleTodo] ГОТОВО, busy снят:', task_uuid, '| after initTodos:', after ? { start_date: after.start_date, task_finish_date: after.task_finish_date, completed: after.completed, number_of_executions: after.number_of_executions } : 'не найден в списке');
                    }
                }, 300)
                return true;
            } catch (err) {
                console.error('Ошибка выполнения задачи:', err);
                this.busyUuids.delete(task_uuid);
                this.completingUuids.delete(task_uuid);
                return false;
            }
        },
        deleteTodo: throttle(async function (task) {
            this.doAuth();
            task = { ...task };
            let task_uuid = task.task_uuid;
            if (this.busyUuids.has(task_uuid)) return;
            this.busyUuids.add(task_uuid);
            try {
                let list = await listEvents(this.$store);
                let exist = list.filter(event => event.description?.includes(task_uuid));
                task.completed = true;
                if(exist.length){
                    await deleteEvent(exist[0])
                    task.break_multiplier = parseFloat(task.break_multiplier) - 0.1;
                    task.repeat_index = toNumber(task.repeat_index) + 0.1;
                } else {

                }
                await makeTaskDone(task, this.$store, {deleted: 1});
            } catch (err) {
                console.error('Ошибка удаления задачи:', err);
            } finally {
                try {
                    await listEvents(this.$store);
                    await this.$store.dispatch("todos/initTodos");
                } catch (err) {
                    console.error('Ошибка обновления данных после удаления:', err);
                }
                this.busyUuids.delete(task_uuid);
            }
        }, 1000),
        isBusy(task_uuid) {
            return this.busyUuids.has(task_uuid);
        },
        isCompleting(task_uuid) {
            return this.completingUuids.has(task_uuid);
        },
        togglePopover(uuid) {
            this.visiblePopover = this.visiblePopover === uuid ? null : uuid;
        },
        startTask(todo) {
            this.doAuth();
            todo = { ...todo };
            if (todo.task_finish_date){
                todo.start_date = Date.now() - todo.task_finish_date;
            } else  {
                todo.start_date = Date.now(); // текущее время в миллисекундах
            }
            this.$store.dispatch("todos/updateTodo", { ...todo });
        },
        async pauseTask(todo) {
            this.doAuth();
            if (this.busyUuids.has(todo.task_uuid)) {
                console.log('[pauseTask] ПРОПУЩЕНО — busy-лок:', todo.task_uuid, todo.task_title);
                return;
            }
            console.log('[pauseTask] ВХОД (стоп запущенной):', { task_uuid: todo.task_uuid, task_title: todo.task_title, start_date: todo.start_date });
            const started = await this.toggleTodo(todo, 'pause');
            if (!started) return;
            setTimeout(()=>{
                const todos = this.$store.getters['todos/getTodos'];
                const fresh = todos.find(t => t.task_uuid === todo.task_uuid);
                const next = fresh ? { ...fresh } : { ...todo };
                next.task_finish_date = 1;
                next.start_date = 0;
                this.$store.dispatch("todos/updateTodo", next);
                console.log('[pauseTask] setTimeout(600): task_finish_date=1, start_date=0 → updateTodo:', todo.task_uuid);
            }, 600)
        },
        doAuth() {
            let api = window.GoogleSheetDB || new GoogleSheetDB();
            if (api.expired()){
                document.getElementById('authorize_button').click()
            }
        }
    },
    async mounted() {
        this.$store.dispatch("todos/initTodos");
        await listEvents(this.$store);
        this.timer = setInterval(() => {
            this.currentTime = new Date().getTime();
        }, 1000);
        this.log = await calcExecutions(this.$store);
        this.selectedFilter = this.filter;
    }
};
</script>

<style scoped>
.neumorphic-radio-group {
    display: flex;
    gap: 10px;
    padding: 10px;
    background: #e0e0e0; /* общий фон */
    border-radius: 20px;
}

.neumorphic-button {
    background: #e0e0e0;
    border: none;
    border-radius: 12px;
    padding: 10px 20px;
    font-size: 14px;
    cursor: pointer;
    transition: all 0.2s ease;
    box-shadow: 4px 4px 8px #bebebe,
    -4px -4px 8px #ffffff;
}

/* Активная (впуклая) кнопка */
.el-radio-button__original-radio:checked + .neumorphic-button,
.el-radio-button.is-active.neumorphic-button {
    box-shadow: inset 4px 4px 8px #bebebe,
    inset -4px -4px 8px #ffffff;
}

/* Hover эффект для большей интерактивности */
.neumorphic-button:hover {
    box-shadow: 2px 2px 4px #bebebe,
    -2px -2px 4px #ffffff;
}

</style>
